def clean(df):
    df = df.copy()
    df = df.drop_duplicates()

    if 'island' in df.columns:
        df['island'] = df['island'].astype(str).str.strip()

    if 'sex' in df.columns:
        df['sex'] = df['sex'].astype(str).str.strip().str.lower()
        df['sex'] = df['sex'].replace({'nan': pd.NA, '': pd.NA})

    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(
            df['body_mass_g'].astype(str).str.replace(',', '', regex=False),
            errors='coerce'
        )
        bm = df['body_mass_g']
        mask = (bm > 6500) & ((bm / 1000).between(2500, 6500))
        df.loc[mask, 'body_mass_g'] = bm[mask] / 1000

    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = pd.to_numeric(
            df['flipper_length_mm'], errors='coerce'
        ).abs()

    return df


def answer(df):
    d = clean(df)
    d = d[d['sex'].isin(['male', 'female'])]
    result = d.groupby('sex')['body_mass_g'].mean().dropna()
    return {str(k): float(v) for k, v in result.items()}
